210→    "$schema": "urn:swissknifeman:task:plan:document:v1",
    "id": "P7-filament-model",
    "title": "P7 — Filament по схеме панели: проверенные предпосылки, ключи, инварианты, пробелы ядра, приёмка",
    "sections": [
      {
