                        TextInput::make('group')->label('Group'),
                    ])
                    ->action(fn (array $data) => $this->write('create', static fn (PanelAccess $access) => $access->permissions()->create(
                        (string) $data['name'],
                        self::text($data['label'] ?? null),
                        self::text($data['group'] ?? null),
